import{_ as e,o as r,c as s,a5 as t}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"3DCGの形と見た目から読む","description":"","frontmatter":{"title":"3DCGの形と見た目から読む","study":{"source":"新規執筆","section":"learning","format":"path","status":"published","domain":"graphics","collection":"foundations","order":4,"summary":"メッシュ、座標とカメラ、材質とテクスチャ、光と画像生成の順に、3DCGの基本用語と役割を図で確かめる読み順。"}},"headers":[],"relativePath":"guide/graphics-basics.md","filePath":"guide/graphics-basics.md"}'),i={name:"guide/graphics-basics.md"};function h(l,a,d,o,n,c){return r(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="_3dcgの形と見た目から読む" tabindex="-1">3DCGの形と見た目から読む <a class="header-anchor" href="#_3dcgの形と見た目から読む" aria-label="Permalink to &quot;3DCGの形と見た目から読む&quot;">​</a></h1><p>「モデルを置く」「マテリアルを設定する」といった操作が、画像とどう結び付くかを知りたいときの入口です。まず形、位置、見た目、画像を作る処理を順に見ます。</p><h2 id="読む順番" tabindex="-1">読む順番 <a class="header-anchor" href="#読む順番" aria-label="Permalink to &quot;読む順番&quot;">​</a></h2><ol><li><a href="/study/graphics/basics/models-and-meshes.html">モデルとメッシュ</a>で、頂点や面がどのように形を表すかを調べます。</li><li><a href="/study/graphics/basics/transforms-and-cameras.html">座標変換とカメラ</a>で、物体の位置と、画面からの見え方を追います。</li><li><a href="/study/graphics/basics/materials-textures-and-shaders.html">マテリアル・テクスチャ・シェーダー</a>で、形の表面にどんな情報を与えるかを見ます。</li><li><a href="/study/graphics/basics/light-and-rendered-images.html">光と描画された画像</a>で、シーンから画像を作る流れをつなげます。</li></ol><h2 id="図から確かめること" tabindex="-1">図から確かめること <a class="header-anchor" href="#図から確かめること" aria-label="Permalink to &quot;図から確かめること&quot;">​</a></h2><ul><li>同じ形でも、位置、カメラ、材質、光が変わると見え方が変わる理由を説明できる。</li><li>頂点やUV、テクスチャなどのデータと、それを使う計算の役割を区別できる。</li><li>ゲーム内の配置から、画面に表示する画像が作られるまでの段階をたどれる。</li></ul><h2 id="さらに調べる" tabindex="-1">さらに調べる <a class="header-anchor" href="#さらに調べる" aria-label="Permalink to &quot;さらに調べる&quot;">​</a></h2><p>数学から確認したいときは<a href="/study/math/rendering/vector.html">ベクトル</a>、<a href="/study/math/rendering/transform.html">座標変換</a>、<a href="/study/math/rendering/camera.html">カメラ</a>へ進みます。GPUでの処理を追う場合は<a href="/study/graphics/pipeline/overview.html">レンダリングパイプライン</a>、制作したモデルの取り込みは<a href="/study/graphics/mesh/mesh-import-and-cooking.html">メッシュのインポート</a>が次の入口です。</p><p>ゲームを組み立てる側の基礎は、<a href="/study/guide/game-development-basics.html">ゲームの動きと構成から読む</a>へ進めます。</p>',9)])])}const p=e(i,[["render",h]]);export{u as __pageData,p as default};
